<script setup>
import { computed } from 'vue'
import { state, changeHours } from '../composables/useMonitor.js'
import { t, themeOptions } from '../composables/useTheme.js'
import { HOURS, probes, probeLabel, probeText, present, bytes, percent, gpuInfo, online, timestamp } from '../utils/metrics.js'
import Sparkline from '../components/Sparkline.vue'
const server = computed(() => state.detail)
const site = computed(() => state.sites[state.page?.site || 0])
const numeric = key => state.rows.map(row => row[key] === null || row[key] === false || row[key] === undefined ? row[key] : Number(row[key]))
const rangeLabel = hours => hours === 0.167 ? '10 min' : hours === 0.5 ? '30 min' : hours < 24 ? `${hours} h` : `${hours / 24} d`
const charts = computed(() => [
  { name: t('cpu'), values: numeric('cpu'), value: `${Number(server.value?.cpu || 0).toFixed(1)}%`, max: 100 },
  { name: t('ram'), values: state.rows.map(row => percent(row.ram_used, row.ram_total)), value: `${bytes(Number(server.value?.ram_used || 0) * 1048576)}`, max: 100 },
  { name: t('swap'), values: state.rows.map(row => percent(row.swap_used, row.swap_total)), value: `${percent(server.value?.swap_used, server.value?.swap_total).toFixed(1)}%`, max: 100 },
  { name: t('disk'), values: state.rows.map(row => percent(row.disk_used, row.disk_total)), value: bytes(Number(server.value?.disk_used || 0) * 1048576), max: 100 },
  ...(themeOptions.value.show_network ? [
    { name: `↓ ${t('download')}`, values: numeric('net_in_speed'), value: `${bytes(server.value?.net_in_speed)}/s` },
    { name: `↑ ${t('upload')}`, values: numeric('net_out_speed'), value: `${bytes(server.value?.net_out_speed)}/s` }
  ] : [])
])
const diskRows = computed(() => state.rows.map(row => { if (typeof row.disk !== 'string') return row.disk; try { return JSON.parse(row.disk) } catch { return null } }))
const disk = computed(() => server.value?.disk && typeof server.value.disk === 'object' ? server.value.disk : null)
const gpu = computed(() => gpuInfo(server.value?.gpu_info))
const probeKeys = computed(() => probes.filter(key => present(server.value?.[`ping_${key}`]) || present(server.value?.[`loss_${key}`]) || state.rows.some(row => present(row[`ping_${key}`]) || present(row[`loss_${key}`]))))
const timeLabel = value => timestamp(value) ? new Date(timestamp(value)).toLocaleTimeString() : '—'
</script>
<template><RouterLink class="back-link" to="/">← {{ t('back') }}</RouterLink><p v-if="state.loading && !server" class="empty">{{ t('loading') }}</p><template v-if="server"><section class="page-heading"><div><p class="eyebrow">{{ server.server_group || t('details') }}</p><h1>{{ server.name || server.id }}</h1><p class="muted">{{ server.os }} <span class="separator">/</span> {{ server.arch }} <span class="separator">/</span> {{ server.region }}</p></div><span class="status" :class="{ offline: !online(server) }"><i></i>{{ t(online(server) ? 'online' : 'offline') }}</span></section><section class="detail-summary panel"><div><span class="muted">CPU</span><strong>{{ server.cpu_info || '—' }}</strong><span>{{ server.cpu_cores || '—' }} vCPU</span></div><div><span class="muted">{{ t('ram') }} / {{ t('disk') }}</span><strong>{{ bytes(Number(server.ram_total) * 1048576) }} / {{ bytes(Number(server.disk_total) * 1048576) }}</strong></div><div><span class="muted">{{ t('traffic') }}</span><strong>↓ {{ bytes(server.net_rx) }} / ↑ {{ bytes(server.net_tx) }}</strong></div><div><span class="muted">{{ t('updated') }}</span><strong>{{ timeLabel(server.last_updated) }}</strong></div></section><div class="section-heading"><h2>{{ t('history') }}</h2><select :value="state.hours" @change="changeHours(Number($event.target.value))" :aria-label="t('history')"><option v-for="hours in HOURS" :key="hours" :value="hours">{{ rangeLabel(hours) }}</option></select></div><p v-if="state.historyLoading" class="muted" role="status">{{ t('loading') }}</p><div class="chart-grid"><article v-for="chart in charts" :key="chart.name" class="chart-card panel"><div class="chart-heading"><h3>{{ chart.name }}</h3><strong>{{ chart.value }}</strong></div><Sparkline v-if="state.rows.length" :values="chart.values" :max="chart.max" :label="chart.name"/><div v-else class="chart-empty muted">{{ t('noHistory') }}</div><div class="chart-axis"><span>{{ timeLabel(state.rows[0]?.timestamp) }}</span><span>{{ timeLabel(state.rows.at(-1)?.timestamp) }}</span></div></article><template v-if="disk"><article v-for="field in ['read_bps', 'write_bps']" :key="field" class="chart-card panel"><div class="chart-heading"><h3>Disk IO · {{ field === 'read_bps' ? 'R' : 'W' }}</h3><strong>{{ bytes(disk[field]) }}/s</strong></div><Sparkline :values="diskRows.map(row => row?.[field])" :label="`Disk IO ${field}`"/></article></template></div><template v-if="probeKeys.length"><div class="section-heading"><h2>{{ t('latency') }} / {{ t('loss') }}</h2><span class="muted">{{ rangeLabel(state.hours) }}</span></div><div class="chart-grid"><article v-for="key in probeKeys" :key="key" class="chart-card panel"><div class="chart-heading"><h3>{{ probeLabel(site.config, key) }}</h3><div><strong v-if="present(server[`ping_${key}`])">{{ probeText(server[`ping_${key}`], ' ms', t('timeout')) }}</strong><span v-if="present(server[`loss_${key}`])" class="muted"> · {{ probeText(server[`loss_${key}`], '%', t('timeout')) }}</span></div></div><Sparkline :values="numeric(`ping_${key}`)" :label="`${probeLabel(site.config, key)} ${t('latency')}`"/><p v-if="state.rows.some(row => row[`ping_${key}`] === null)" class="muted">{{ t('timeout') }}</p><Sparkline :values="numeric(`loss_${key}`)" :max="100" :height="40" :label="`${probeLabel(site.config, key)} ${t('loss')}`"/></article></div></template><template v-if="gpu.length"><div class="section-heading"><h2>GPU</h2></div><div class="chart-grid"><article v-for="item in gpu" :key="item.id" class="panel chart-card"><h3>{{ item.name }}</h3><pre>{{ item.info }}</pre><Sparkline :values="state.rows.map(row => { const info = gpuInfo(row.gpu_info).find(g => String(g.id) === String(item.id))?.info; return info === null || info === undefined ? undefined : Number(info) })" :max="100" :label="item.name"/></article></div></template></template></template>
